def copy_district_legal_config_to_lane_config(apps, schema_editor):
    DistrictLegalConfig = apps.get_model('core', 'DistrictLegalConfig')
    District = apps.get_model('core', 'District')
    LaneConfig = apps.get_model('core', 'LaneConfig')

    for dlc in DistrictLegalConfig.objects.all():
        dist_obj = None
        if dlc.district:
            dist_obj = District.objects.filter(name_en__iexact=dlc.district.strip()).first()
            if not dist_obj:
                dist_obj = District.objects.filter(code__iexact=dlc.district.strip()).first()

        LaneConfig.objects.create(
            district=dist_obj,
            high_min=dlc.tier1_confidence_min if dlc.tier1_confidence_min is not None else 0.80,
            medium_min=dlc.tier2_confidence_min if dlc.tier2_confidence_min is not None else 0.50,
            fast_lane_audit_pct=getattr(dlc, 'fast_lane_audit_pct', 20.0) or 20.0,
            min_sample_size=getattr(dlc, 'min_sample_size_accuracy', 30) or 30,
            recheck_days_low=getattr(dlc, 'recheck_days_low', 30) or 30,
        )


